type BarcodeScanResult = {
	rawValue?: string;
};
type ZxingModule = typeof import('@zxing/library');

type RelabelRow = {
	id: string;
	sourceKey: string;
	targetKey: string;
	value: string;
	selected: boolean;
};

type ScannerMethod = 'barcode' | 'photo';
type CaptureIntent = 'appliance' | 'part' | 'generic';
type PhotoWizardStep = 'capture' | 'confirm-image' | 'review-text' | 'review-fields';
type CameraPoint = { x: number; y: number };
type CameraZoomCapability = { min: number; max: number; step?: number };
type CameraControlCapabilities = {
	zoom: CameraZoomCapability | null;
	supportsFocusPoint: boolean;
	focusModes: string[];
};

const FIELD_LABELS: Record<string, string> = {
	type: 'Appliance type',
	assetType: 'Appliance type',
	brand: 'Brand',
	manufacturer: 'Manufacturer',
	model: 'Model',
	serialNumber: 'Serial number',
	serial: 'Serial number',
	partNumber: 'Part number',
	filterSize: 'Filter size',
	specNotes: 'Service notes',
	name: 'Name',
	category: 'Category',
	details: 'Details',
	size: 'Size',
	material: 'Material',
	voltage: 'Voltage',
	mervRating: 'MERV rating',
	compatibility: 'Compatibility',
	replacementInterval: 'Replacement interval',
	notes: 'Notes',
};

const DEFAULT_CAMERA_CONTROLS: CameraControlCapabilities = {
	zoom: null,
	supportsFocusPoint: false,
	focusModes: [],
};

const clamp = (value: number, min: number, max: number): number => Math.min(max, Math.max(min, value));

const getPointerDistance = (first: CameraPoint, second: CameraPoint): number =>
	Math.hypot(first.x - second.x, first.y - second.y);

const formatFieldLabel = (key: string): string => {
	const trimmed = key.trim();
	if (!trimmed) return '';
	if (FIELD_LABELS[trimmed]) return FIELD_LABELS[trimmed];
	const spaced = trimmed
		.replace(/([a-z])([A-Z])/g, '$1 $2')
		.replace(/[_-]+/g, ' ')
		.replace(/\s+/g, ' ')
		.trim();
	return spaced ? spaced.charAt(0).toUpperCase() + spaced.slice(1) : trimmed;
};

interface BarcodeScannerModalProps {
	isOpen: boolean;
	title?: string;
	defaultMethod?: ScannerMethod;
	captureIntent?: CaptureIntent;
	onClose: () => void;
	onDetected: (value: string) => void;
}

export const BarcodeScannerModal: React.FC<BarcodeScannerModalProps> = ({
	isOpen,
	title = 'Capture Assistant',
	defaultMethod = 'barcode',
	captureIntent = 'generic',
	onClose,
	onDetected,
}) => {
	const videoRef = useRef<HTMLVideoElement | null>(null);
	const photoInputRef = useRef<HTMLInputElement | null>(null);
	const streamRef = useRef<MediaStream | null>(null);
	const rafRef = useRef<number | null>(null);
	const zxingModuleRef = useRef<ZxingModule | null>(null);
	const zxingReaderRef = useRef<any | null>(null);
	const zxingStopRef = useRef<(() => void) | null>(null);
	const activeVideoTrackRef = useRef<MediaStreamTrack | null>(null);
	const [error, setError] = useState<string>('');
	const [manualValue, setManualValue] = useState('');
	const [capturedValue, setCapturedValue] = useState('');
	const [analysis, setAnalysis] = useState<BarcodePayloadAnalysis | null>(null);
	const [relabelRows, setRelabelRows] = useState<RelabelRow[]>([]);
	const [activeMethod, setActiveMethod] = useState<ScannerMethod>(defaultMethod);
	const [photoWizardStep, setPhotoWizardStep] = useState<PhotoWizardStep>('capture');
	const [selectedImageFile, setSelectedImageFile] = useState<File | null>(null);
	const [selectedImagePreview, setSelectedImagePreview] = useState('');
	const [isExtractingText, setIsExtractingText] = useState(false);
	const [ocrError, setOcrError] = useState('');
	const [captureEngineLabel, setCaptureEngineLabel] = useState('');
	const [isTorchAvailable, setIsTorchAvailable] = useState(false);
	const [isTorchOn, setIsTorchOn] = useState(false);
	const [cameraControls, setCameraControls] = useState<CameraControlCapabilities>(DEFAULT_CAMERA_CONTROLS);
	const [cameraZoom, setCameraZoom] = useState(1);
	const [cameraGestureMessage, setCameraGestureMessage] = useState('');
	const [focusPoint, setFocusPoint] = useState<CameraPoint | null>(null);
	const cameraPointersRef = useRef<Map<number, CameraPoint>>(new Map());
	const pinchStateRef = useRef<{ distance: number; zoom: number } | null>(null);
	const tapCandidateRef = useRef<{ pointerId: number; x: number; y: number; moved: boolean } | null>(null);
	const focusReticleTimeoutRef = useRef<number | null>(null);

	const supportsBarcodeDetector = useMemo(
		() => typeof (window as any).BarcodeDetector !== 'undefined',
		[],
	);
	const supportsCameraAccess = useMemo(
		() =>
			typeof navigator !== 'undefined' &&
			!!navigator.mediaDevices &&
			typeof navigator.mediaDevices.getUserMedia === 'function',
		[],
	);

	const confidenceFromField = useCallback(
		(sourceKey: string, targetKey: string, value: string): 'high' | 'medium' | 'low' => {
			const normalizedKey = `${sourceKey} ${targetKey}`.toLowerCase();
			const cleanedValue = value.trim();
			if (!cleanedValue || cleanedValue.length < 2) return 'low';

			const isIdentifierField = /(serial|model|part|gtin|upc|ean|pn|sn)/i.test(
				normalizedKey,
			);
			const isDescriptorField = /(brand|manufacturer|type|size|material|notes|details)/i.test(
				normalizedKey,
			);

			if (isIdentifierField && /^[A-Za-z0-9._/-]{5,}$/.test(cleanedValue)) return 'high';
			if (isIdentifierField || isDescriptorField) return 'medium';
			return 'low';
		},
		[],
	);

	const stopScanner = useCallback(() => {
		if (rafRef.current) {
			cancelAnimationFrame(rafRef.current);
			rafRef.current = null;
		}
		if (streamRef.current) {
			streamRef.current.getTracks().forEach((track) => track.stop());
			streamRef.current = null;
		}
		activeVideoTrackRef.current = null;
		cameraPointersRef.current.clear();
		pinchStateRef.current = null;
		tapCandidateRef.current = null;
		if (focusReticleTimeoutRef.current) {
			window.clearTimeout(focusReticleTimeoutRef.current);
			focusReticleTimeoutRef.current = null;
		}
		setFocusPoint(null);
		setCameraControls(DEFAULT_CAMERA_CONTROLS);
		setCameraZoom(1);
		setCameraGestureMessage('');
		setIsTorchAvailable(false);
		setIsTorchOn(false);
		if (zxingStopRef.current) {
			zxingStopRef.current();
			zxingStopRef.current = null;
		}
	}, []);

	const syncTorchAvailability = useCallback((stream: MediaStream | null) => {
		const nextTrack = stream?.getVideoTracks?.()[0] || null;
		activeVideoTrackRef.current = nextTrack;
		const capabilities = nextTrack?.getCapabilities?.() as MediaTrackCapabilities & {
			torch?: boolean;
			zoom?: CameraZoomCapability;
			focusMode?: string[];
			pointsOfInterest?: boolean;
		};
		const settings = nextTrack?.getSettings?.() as MediaTrackSettings & { zoom?: number };
		const hasTorch = Boolean(capabilities?.torch);
		const zoomCapability = capabilities?.zoom;
		const hasZoom =
			!!zoomCapability &&
			Number.isFinite(zoomCapability.min) &&
			Number.isFinite(zoomCapability.max) &&
			zoomCapability.max > zoomCapability.min;
		const focusModes = Array.isArray(capabilities?.focusMode) ? capabilities.focusMode : [];
		const supportsFocusPoint = Boolean(capabilities?.pointsOfInterest) || focusModes.length > 0;

		setIsTorchAvailable(hasTorch);
		if (!hasTorch) {
			setIsTorchOn(false);
		}
		setCameraControls({
			zoom: hasZoom ? zoomCapability : null,
			supportsFocusPoint,
			focusModes,
		});
		setCameraZoom(
			hasZoom ? clamp(settings?.zoom ?? zoomCapability.min, zoomCapability.min, zoomCapability.max) : 1,
		);
		setCameraGestureMessage('');
	}, []);

	const toggleTorch = useCallback(async () => {
		const track = activeVideoTrackRef.current;
		if (!track || !isTorchAvailable) return;

		const nextTorchState = !isTorchOn;
		try {
			await track.applyConstraints({
				advanced: [{ torch: nextTorchState } as MediaTrackConstraintSet],
			});
			setIsTorchOn(nextTorchState);
		} catch {
			setError('Flashlight is not available on this camera.');
		}
	}, [isTorchAvailable, isTorchOn]);

	const applyCameraConstraints = useCallback(async (constraints: Record<string, unknown>) => {
		const track = activeVideoTrackRef.current;
		if (!track || track.readyState !== 'live') return false;

		try {
			await track.applyConstraints({
				advanced: [constraints as MediaTrackConstraintSet],
			});
			return true;
		} catch {
			return false;
		}
	}, []);

	const applyCameraZoom = useCallback(
		async (nextZoom: number, announce = true) => {
			const zoomCapability = cameraControls.zoom;
			if (!zoomCapability) return false;

			const steppedZoom = zoomCapability.step
				? Math.round(nextZoom / zoomCapability.step) * zoomCapability.step
				: nextZoom;
			const clampedZoom = Number(
				clamp(steppedZoom, zoomCapability.min, zoomCapability.max).toFixed(2),
			);
			const applied = await applyCameraConstraints({ zoom: clampedZoom });
			if (applied) {
				setCameraZoom(clampedZoom);
				if (announce) {
					setCameraGestureMessage(`Zoom ${clampedZoom.toFixed(1)}x`);
				}
			}
			return applied;
		},
		[applyCameraConstraints, cameraControls.zoom],
	);

	const focusCameraAtPoint = useCallback(
		async (point: CameraPoint, rect: DOMRect) => {
			const focusModes = cameraControls.focusModes;
			const preferredFocusMode = focusModes.includes('single-shot')
				? 'single-shot'
				: focusModes.includes('continuous')
					? 'continuous'
					: focusModes[0];
			const normalizedPoint = {
				x: clamp(point.x / rect.width, 0, 1),
				y: clamp(point.y / rect.height, 0, 1),
			};
			const focusAttempts = [
				preferredFocusMode
					? { pointsOfInterest: [normalizedPoint], focusMode: preferredFocusMode }
					: { pointsOfInterest: [normalizedPoint] },
				{ pointsOfInterest: [normalizedPoint] },
				preferredFocusMode ? { focusMode: preferredFocusMode } : null,
			].filter(Boolean) as Array<Record<string, unknown>>;

			for (const attempt of focusAttempts) {
				if (await applyCameraConstraints(attempt)) {
					setCameraGestureMessage('Focus adjusted');
					return true;
				}
			}

			setCameraGestureMessage('Tap-to-focus is not available on this camera.');
			return false;
		},
		[applyCameraConstraints, cameraControls.focusModes],
	);

	const showFocusReticle = useCallback((point: CameraPoint) => {
		setFocusPoint(point);
		if (focusReticleTimeoutRef.current) {
			window.clearTimeout(focusReticleTimeoutRef.current);
		}
		focusReticleTimeoutRef.current = window.setTimeout(() => {
			setFocusPoint(null);
			focusReticleTimeoutRef.current = null;
		}, 700);
	}, []);

	const getCameraPointerPoint = (event: React.PointerEvent<HTMLDivElement>): CameraPoint => {
		const rect = event.currentTarget.getBoundingClientRect();
		return {
			x: event.clientX - rect.left,
			y: event.clientY - rect.top,
		};
	};

	const handleCameraPointerDown = useCallback(
		(event: React.PointerEvent<HTMLDivElement>) => {
			if (!activeVideoTrackRef.current) return;
			event.preventDefault();
			event.currentTarget.setPointerCapture?.(event.pointerId);
			const point = getCameraPointerPoint(event);
			cameraPointersRef.current.set(event.pointerId, point);

			if (cameraPointersRef.current.size === 1) {
				tapCandidateRef.current = {
					pointerId: event.pointerId,
					x: event.clientX,
					y: event.clientY,
					moved: false,
				};
				return;
			}

			if (cameraPointersRef.current.size === 2) {
				const [first, second] = Array.from(cameraPointersRef.current.values());
				pinchStateRef.current = { distance: getPointerDistance(first, second), zoom: cameraZoom };
				tapCandidateRef.current = null;
			}
		},
		[cameraZoom],
	);

	const handleCameraPointerMove = useCallback(
		(event: React.PointerEvent<HTMLDivElement>) => {
			if (!cameraPointersRef.current.has(event.pointerId)) return;
			event.preventDefault();
			const point = getCameraPointerPoint(event);
			cameraPointersRef.current.set(event.pointerId, point);

			const tapCandidate = tapCandidateRef.current;
			if (tapCandidate?.pointerId === event.pointerId) {
				const movedDistance = Math.hypot(event.clientX - tapCandidate.x, event.clientY - tapCandidate.y);
				if (movedDistance > 8) {
					tapCandidateRef.current = { ...tapCandidate, moved: true };
				}
			}

			if (cameraPointersRef.current.size !== 2 || !pinchStateRef.current || !cameraControls.zoom) return;
			const [first, second] = Array.from(cameraPointersRef.current.values());
			const nextDistance = getPointerDistance(first, second);
			if (pinchStateRef.current.distance <= 0) return;
			const nextZoom = pinchStateRef.current.zoom * (nextDistance / pinchStateRef.current.distance);
			void applyCameraZoom(nextZoom, false);
			setCameraGestureMessage('Pinch to zoom');
		},
		[applyCameraZoom, cameraControls.zoom],
	);

	const handleCameraPointerEnd = useCallback(
		(event: React.PointerEvent<HTMLDivElement>) => {
			if (!cameraPointersRef.current.has(event.pointerId)) return;
			event.preventDefault();
			const point = getCameraPointerPoint(event);
			const rect = event.currentTarget.getBoundingClientRect();
			const tapCandidate = tapCandidateRef.current;
			const isTap =
				tapCandidate?.pointerId === event.pointerId &&
				!tapCandidate.moved &&
				cameraPointersRef.current.size === 1;

			cameraPointersRef.current.delete(event.pointerId);
			event.currentTarget.releasePointerCapture?.(event.pointerId);
			if (cameraPointersRef.current.size < 2) {
				pinchStateRef.current = null;
			}
			if (tapCandidate?.pointerId === event.pointerId) {
				tapCandidateRef.current = null;
			}

			if (!isTap) return;
			showFocusReticle(point);
			if (!cameraControls.supportsFocusPoint) {
				setCameraGestureMessage('Tap-to-focus is not available on this camera.');
				return;
			}
			void focusCameraAtPoint(point, rect);
		},
		[cameraControls.supportsFocusPoint, focusCameraAtPoint, showFocusReticle],
	);
	const loadZxingModule = useCallback(async () => {
		if (!zxingModuleRef.current) {
			zxingModuleRef.current = await import('@zxing/library');
		}
		return zxingModuleRef.current;
	}, []);

	const getZxingReader = useCallback(async () => {
		if (!zxingReaderRef.current) {
			const zxing = await loadZxingModule();
			const hints = new Map();
			hints.set(zxing.DecodeHintType.POSSIBLE_FORMATS, [
				zxing.BarcodeFormat.CODE_128,
				zxing.BarcodeFormat.CODE_39,
				zxing.BarcodeFormat.EAN_13,
				zxing.BarcodeFormat.EAN_8,
				zxing.BarcodeFormat.UPC_A,
				zxing.BarcodeFormat.UPC_E,
				zxing.BarcodeFormat.QR_CODE,
				zxing.BarcodeFormat.DATA_MATRIX,
			]);
			zxingReaderRef.current = new zxing.BrowserMultiFormatReader(hints);
		}
		return zxingReaderRef.current;
	}, [loadZxingModule]);

	const commitValue = useCallback((value: string) => {
		const trimmed = value.trim();
		if (!trimmed) return;
		onDetected(trimmed);
		stopScanner();
		onClose();
	}, [onClose, onDetected, stopScanner]);

	const buildRowsFromNormalized = useCallback(
		(
			normalizedFields: Record<string, unknown>,
			prefix: string,
		): RelabelRow[] =>
			Object.entries(normalizedFields)
				.filter(([, value]) => typeof value === 'string' && value.trim())
				.map(([key, value], index) => ({
					id: `${prefix}-${index}-${key}`,
					sourceKey: formatFieldLabel(key),
					targetKey: formatFieldLabel(key),
					value: String(value),
					selected: true,
				})),
		[],
	);

	const buildRelabelRows = useCallback((nextAnalysis: BarcodePayloadAnalysis): RelabelRow[] => {
		if (captureIntent === 'appliance') {
			const rows = buildRowsFromNormalized(nextAnalysis.normalized.device, 'device');
			if (rows.length > 0) return rows;
		}

		if (captureIntent === 'part') {
			const rows = buildRowsFromNormalized(nextAnalysis.normalized.part, 'part');
			if (rows.length > 0) return rows;
		}

		const rows: RelabelRow[] = [];
		const pairEntries = Object.entries(nextAnalysis.keyValuePairs);

		if (pairEntries.length > 0) {
			pairEntries.forEach(([key, value], index) => {
				rows.push({
					id: `pair-${index}-${key}`,
					sourceKey: formatFieldLabel(key),
					targetKey: formatFieldLabel(key),
					value,
					selected: true,
				});
			});
			return rows;
		}

		const mergedNormalized: Record<string, string> = {};
		Object.entries(nextAnalysis.normalized.device).forEach(([key, value]) => {
			if (value) mergedNormalized[key] = String(value);
		});
		Object.entries(nextAnalysis.normalized.part).forEach(([key, value]) => {
			if (value && !mergedNormalized[key]) mergedNormalized[key] = String(value);
		});

		Object.entries(mergedNormalized).forEach(([key, value], index) => {
			rows.push({
				id: `normalized-${index}-${key}`,
				sourceKey: formatFieldLabel(key),
				targetKey: formatFieldLabel(key),
				value,
				selected: true,
			});
		});

		return rows;
	}, [buildRowsFromNormalized, captureIntent]);

	const captureValue = useCallback((value: string) => {
		const trimmed = value.trim();
		if (!trimmed) return;
		const nextAnalysis = analyzeBarcodePayload(trimmed);
		setCapturedValue(trimmed);
		setAnalysis(nextAnalysis);
		setRelabelRows(buildRelabelRows(nextAnalysis));
		if (activeMethod === 'photo') {
			setPhotoWizardStep('review-fields');
		}
		stopScanner();
	}, [activeMethod, buildRelabelRows, stopScanner]);

	const resetPhotoCapture = useCallback(() => {
		setManualValue('');
		setCapturedValue('');
		setAnalysis(null);
		setRelabelRows([]);
		setSelectedImageFile(null);
		setSelectedImagePreview('');
		setIsExtractingText(false);
		setOcrError('');
		setCaptureEngineLabel('');
		setPhotoWizardStep('capture');
	}, []);

	const selectMethod = useCallback((method: ScannerMethod) => {
		setActiveMethod(method);
		setManualValue('');
		setCapturedValue('');
		setAnalysis(null);
		setRelabelRows([]);
		setSelectedImageFile(null);
		setSelectedImagePreview('');
		setIsExtractingText(false);
		setOcrError('');
		setCaptureEngineLabel('');
		setPhotoWizardStep('capture');
	}, []);

	const toggleRelabelRow = (id: string) => {
		setRelabelRows((prev) =>
			prev.map((row) => (row.id === id ? { ...row, selected: !row.selected } : row)),
		);
	};

	const updateRelabelRow = (id: string, field: 'targetKey' | 'value', value: string) => {
		setRelabelRows((prev) =>
			prev.map((row) => (row.id === id ? { ...row, [field]: value } : row)),
		);
	};

	const buildApplyValue = useCallback((): string => {
		const selected = relabelRows.filter(
			(row) => row.selected && row.targetKey.trim() && row.value.trim(),
		);
		if (selected.length === 0) return capturedValue;
		return selected
			.map((row) => `${row.targetKey.trim()}: ${row.value.trim()}`)
			.join('; ');
	}, [capturedValue, relabelRows]);

	const extractTextFromImage = useCallback(
		async (file: File) => {
			setOcrError('');
			setIsExtractingText(true);
			setPhotoWizardStep('review-text');
			try {
				const zxingReader = await getZxingReader();
				const imageUrl = URL.createObjectURL(file);
				try {
					const decodedBarcode = await zxingReader.decodeFromImageUrl(imageUrl);
					const decodedValue = decodedBarcode.getText().trim();
					if (decodedValue) {
						setCaptureEngineLabel('ZXing barcode decode from image');
						setManualValue(decodedValue);
						return;
					}
				} catch {
					// Fall through to OCR extraction when no machine-readable barcode is found.
				} finally {
					URL.revokeObjectURL(imageUrl);
				}

				const tesseractModule = await import('tesseract.js');
				const worker = await (tesseractModule as any).createWorker('eng');
				const result = await worker.recognize(file);
				await worker.terminate();

				const extractedText = String(result?.data?.text || '').trim();
				if (!extractedText) {
					setOcrError('No readable text was detected on this image. Try a clearer photo.');
					setPhotoWizardStep('confirm-image');
					return;
				}

				setCaptureEngineLabel('OCR text extraction');
				setManualValue(extractedText);
			} catch {
				setOcrError('Unable to extract text from this image. Please try another photo.');
				setPhotoWizardStep('confirm-image');
			} finally {
				setIsExtractingText(false);
			}
		},
		[getZxingReader],
	);

	const handlePhotoSelected = (event: React.ChangeEvent<HTMLInputElement>) => {
		const file = event.target.files?.[0];
		if (!file) return;
		setSelectedImageFile(file);
		setOcrError('');
		setManualValue('');
		setCapturedValue('');
		setAnalysis(null);
		setRelabelRows([]);

		const reader = new FileReader();
		reader.onload = () => {
			setSelectedImagePreview(String(reader.result || ''));
			setPhotoWizardStep('confirm-image');
			stopScanner();
		};
		reader.readAsDataURL(file);
	};

	const capturePhotoFromCamera = useCallback(async () => {
		const video = videoRef.current;
		if (!video || video.videoWidth === 0 || video.videoHeight === 0) {
			setOcrError('Camera preview is not ready yet. Try again in a moment.');
			return;
		}

		setOcrError('');
		const canvas = document.createElement('canvas');
		canvas.width = video.videoWidth;
		canvas.height = video.videoHeight;
		const context = canvas.getContext('2d');
		if (!context) {
			setOcrError('Could not capture this image. Try again.');
			return;
		}

		context.drawImage(video, 0, 0, canvas.width, canvas.height);
		const previewUrl = canvas.toDataURL('image/jpeg', 0.92);
		setSelectedImagePreview(previewUrl);

		const blob = await new Promise<Blob | null>((resolve) => {
			canvas.toBlob((value) => resolve(value), 'image/jpeg', 0.92);
		});
		if (!blob) {
			setOcrError('Could not capture this image. Try again.');
			return;
		}

		const capturedFile = new File([blob], `maintley-label-${Date.now()}.jpg`, {
			type: 'image/jpeg',
		});
		setSelectedImageFile(capturedFile);
		setPhotoWizardStep('confirm-image');
		stopScanner();
	}, [stopScanner]);

	useEffect(() => {
		if (!isOpen) {
			stopScanner();
			setError('');
			setManualValue('');
			setCapturedValue('');
			setAnalysis(null);
			setRelabelRows([]);
			setActiveMethod(defaultMethod);
			setPhotoWizardStep('capture');
			setSelectedImageFile(null);
			setSelectedImagePreview('');
			setIsExtractingText(false);
			setOcrError('');
			setCaptureEngineLabel('');
			return;
		}

		if (analysis) {
			stopScanner();
			return;
		}

		if (activeMethod === 'photo' && photoWizardStep !== 'capture') {
			stopScanner();
			return;
		}

		if (!supportsCameraAccess) {
			setError('Camera access is not available in this browser. Use manual paste below.');
			return;
		}

		let cancelled = false;
		const setup = async () => {
			try {
				setError(
					activeMethod === 'barcode' && !supportsBarcodeDetector
						? 'Native browser barcode detection is unavailable. Maintley will use ZXing decoding instead.'
						: '',
				);
				const stream = await navigator.mediaDevices.getUserMedia({
					video: { facingMode: 'environment' },
					audio: false,
				});
				if (cancelled) {
					stream.getTracks().forEach((track) => track.stop());
					return;
				}

				streamRef.current = stream;
				syncTorchAvailability(stream);
				const video = videoRef.current;
				if (!video) return;
				video.srcObject = stream;
				await video.play();

				if (activeMethod !== 'barcode') {
					setCaptureEngineLabel('Camera capture for OCR');
					return;
				}

				if (!supportsBarcodeDetector) {
					setCaptureEngineLabel('ZXing live decode');
				}

				let captured = false;
				const handleCapture = (value: string, engine: string) => {
					if (captured || cancelled) return;
					captured = true;
					setCaptureEngineLabel(engine);
					captureValue(value);
				};

				if (supportsBarcodeDetector) {
					const DetectorCtor = (window as any).BarcodeDetector;
					const detector = new DetectorCtor({
						formats: [
							'code_128',
							'code_39',
							'ean_13',
							'ean_8',
							'upc_a',
							'upc_e',
							'qr_code',
						],
					});

					const tick = async () => {
						if (!videoRef.current || captured || cancelled) return;
						try {
							const results = (await detector.detect(videoRef.current)) as BarcodeScanResult[];
							if (results.length > 0 && results[0].rawValue) {
								handleCapture(results[0].rawValue, 'Native browser barcode detector');
								return;
							}
						} catch {
							// Keep scanning even if one frame errors.
						}
						rafRef.current = requestAnimationFrame(tick);
					};

					rafRef.current = requestAnimationFrame(tick);
				}

				const zxing = await loadZxingModule();
				const zxingReader = await getZxingReader();
				await zxingReader.decodeFromStream(
					stream,
					video,
					(result, decodeError) => {
						if (captured || cancelled) return;
						if (result?.getText()) {
							handleCapture(result.getText(), 'ZXing live decode');
							return;
						}
						if (
							decodeError &&
							!(decodeError instanceof zxing.NotFoundException) &&
							!supportsBarcodeDetector
						) {
							setError('ZXing could not decode the current frame. Try better lighting or move closer.');
						}
					},
				);
				zxingStopRef.current = () => zxingReader.reset();
			} catch {
				setError('Unable to access camera. Check browser permissions and try again.');
			}
		};

		setup();

		return () => {
			cancelled = true;
			stopScanner();
		};
	}, [
		activeMethod,
		analysis,
		captureValue,
		capturePhotoFromCamera,
		defaultMethod,
		getZxingReader,
		isOpen,
		loadZxingModule,
		photoWizardStep,
		syncTorchAvailability,
		stopScanner,
		supportsBarcodeDetector,
		supportsCameraAccess,
	]);

	const tabLabels = useMemo(() => {
		if (captureIntent === 'appliance') {
			return {
				barcode: 'Barcode / QR',
				photo: 'Appliance Label',
			};
		}

		return {
			barcode: 'Barcode / QR Scan',
			photo: 'Label Photo (OCR)',
		};
	}, [captureIntent]);
	const hasSelectedRelabelRows = relabelRows.some(
		(row) => row.selected && row.targetKey.trim() && row.value.trim(),
	);
	const inspectorTitle =
		captureIntent === 'appliance'
			? 'Recognized appliance details'
			: captureIntent === 'part'
				? 'Recognized part details'
				: 'Scanned data inspector';
	const inspectorHint =
		captureIntent === 'appliance'
			? 'Review the fields Maintley recognized from the label. Only checked fields will be applied to this appliance.'
			: captureIntent === 'part'
				? 'Review the fields Maintley recognized. Only checked fields will be applied to this part.'
				: 'Review detected key-value pairs, GS1 segments, and normalized mappings before applying.';
	const cameraGestureHint = useMemo(() => {
		const hints: string[] = [];
		if (cameraControls.zoom) hints.push('Pinch to zoom');
		if (cameraControls.supportsFocusPoint) hints.push('Tap to focus');
		return hints.join('. ');
	}, [cameraControls.supportsFocusPoint, cameraControls.zoom]);
	const cameraHintText = cameraGestureMessage || cameraGestureHint;
	const renderCameraPreview = () => (
		<VideoWrap
			onPointerDown={handleCameraPointerDown}
			onPointerMove={handleCameraPointerMove}
			onPointerUp={handleCameraPointerEnd}
			onPointerCancel={handleCameraPointerEnd}
			aria-label='Camera preview'>
			<Video ref={videoRef} playsInline muted />
			{focusPoint && <FocusReticle $x={focusPoint.x} $y={focusPoint.y} />}
			{cameraHintText && <CameraGestureHint>{cameraHintText}</CameraGestureHint>}
		</VideoWrap>
	);
	if (!isOpen) return null;

	return (
		<Overlay>
			<Card>
				<Header>
					<Title>{title}</Title>
					<CloseButton
						type='button'
						onClick={() => {
							stopScanner();
							onClose();
						}}>
						Close
					</CloseButton>
				</Header>
				<Body>
					<GuidanceCard>
						<InspectorTitle style={{ fontSize: '12px' }}>Capture assistant flow</InspectorTitle>
						<Helper>
							Capture first, then confirm what should be applied. Nothing is saved until you tap an Apply button.
						</Helper>
					</GuidanceCard>
					<MethodTabs>
						<MethodTabButton
							type='button'
							$active={activeMethod === 'barcode'}
							onClick={() => selectMethod('barcode')}>
							{tabLabels.barcode}
						</MethodTabButton>
						<MethodTabButton
							type='button'
							$active={activeMethod === 'photo'}
							onClick={() => selectMethod('photo')}>
							{tabLabels.photo}
						</MethodTabButton>
					</MethodTabs>
					{activeMethod === 'photo' && (
						<WizardSteps>
							<WizardStepItem
								$active={photoWizardStep === 'capture'}
								$complete={photoWizardStep !== 'capture'}>
								1. Capture
							</WizardStepItem>
							<WizardStepItem
								$active={photoWizardStep === 'confirm-image'}
								$complete={photoWizardStep === 'review-text' || photoWizardStep === 'review-fields'}>
								2. Confirm image
							</WizardStepItem>
							<WizardStepItem
								$active={photoWizardStep === 'review-text'}
								$complete={photoWizardStep === 'review-fields'}>
								3. Validate text
							</WizardStepItem>
							<WizardStepItem $active={photoWizardStep === 'review-fields'}>
								4. Apply fields
							</WizardStepItem>
						</WizardSteps>
					)}

					{!analysis && activeMethod === 'barcode' && (
						<>
							{renderCameraPreview()}
							<CameraToolbar>
								<GhostButton
									type='button'
									onClick={() => void toggleTorch()}
									disabled={!isTorchAvailable}>
									{isTorchOn ? 'Flashlight Off' : 'Flashlight On'}
								</GhostButton>
							</CameraToolbar>
							<Helper>
								Use this when the label has a UPC/EAN/QR code. Appliance barcodes may not include full make/model/serial data.
							</Helper>
							<EngineHint>Engines: Native BarcodeDetector + ZXing fallback</EngineHint>
						</>
					)}

					{!analysis && activeMethod === 'photo' && photoWizardStep === 'capture' && (
						<>
							{supportsCameraAccess && (
								<>
									{renderCameraPreview()}
									<CameraToolbar>
										<GhostButton
											type='button'
											onClick={() => void toggleTorch()}
											disabled={!isTorchAvailable}>
											{isTorchOn ? 'Flashlight Off' : 'Flashlight On'}
										</GhostButton>
										<ActionButton
											type='button'
											onClick={() => void capturePhotoFromCamera()}>
											Capture From Camera
										</ActionButton>
									</CameraToolbar>
								</>
							)}
							<Helper>
								Take or upload the equipment label. Maintley will suggest model, serial, brand, and service fields for review.
							</Helper>
							<Helper>
								Tip: fill the frame with the label, reduce glare, and keep text horizontal for best OCR results.
							</Helper>
							<Row>
								<ActionButton
									type='button'
									onClick={() => photoInputRef.current?.click()}>
									Choose Label Image
								</ActionButton>
							</Row>
							<HiddenFileInput
								ref={photoInputRef}
								type='file'
								accept='image/*'
								capture='environment'
								onChange={handlePhotoSelected}
							/>
							{ocrError && <ErrorText>{ocrError}</ErrorText>}
						</>
					)}
					{!analysis && activeMethod === 'photo' && photoWizardStep === 'confirm-image' && (
						<InspectorCard>
							<InspectorTitle>Confirm the label photo</InspectorTitle>
							<InspectorHint>
								Make sure the model and serial areas are readable. If glare or blur hides the label, retake it before Maintley reads the text.
							</InspectorHint>
							{selectedImagePreview && (
								<PreviewImage src={selectedImagePreview} alt='Appliance label preview' />
							)}
							<Row>
								<ActionButton
									type='button'
									disabled={!selectedImageFile || isExtractingText}
									onClick={() => {
										if (selectedImageFile) {
											void extractTextFromImage(selectedImageFile);
										}
									}}>
									{isExtractingText ? 'Reading Text...' : 'Use This Image'}
								</ActionButton>
								<GhostButton type='button' onClick={resetPhotoCapture}>
									Retake
								</GhostButton>
								<GhostButton
									type='button'
									onClick={() => photoInputRef.current?.click()}>
									Choose Different Image
								</GhostButton>
							</Row>
							<HiddenFileInput
								ref={photoInputRef}
								type='file'
								accept='image/*'
								capture='environment'
								onChange={handlePhotoSelected}
							/>
							{ocrError && <ErrorText>{ocrError}</ErrorText>}
						</InspectorCard>
					)}
					{!analysis && activeMethod === 'photo' && photoWizardStep === 'review-text' && (
						<InspectorCard>
							<InspectorTitle>Validate recognized text</InspectorTitle>
							<InspectorHint>
								Fix obvious OCR mistakes before Maintley turns the text into appliance fields.
							</InspectorHint>
							{selectedImagePreview && (
								<PreviewImage src={selectedImagePreview} alt='Appliance label preview' />
							)}
							<TextArea
								value={manualValue}
								onChange={(event) => setManualValue(event.target.value)}
								placeholder='Recognized label text will appear here'
								disabled={isExtractingText}
							/>
							{captureEngineLabel && <EngineHint>Captured via: {captureEngineLabel}</EngineHint>}
							{ocrError && <ErrorText>{ocrError}</ErrorText>}
							<Row>
								<ActionButton
									type='button'
									disabled={!manualValue.trim() || isExtractingText}
									onClick={() => captureValue(manualValue)}>
									Review Recognized Fields
								</ActionButton>
								<GhostButton
									type='button'
									disabled={!selectedImageFile || isExtractingText}
									onClick={() => {
										if (selectedImageFile) {
											void extractTextFromImage(selectedImageFile);
										}
									}}>
									{isExtractingText ? 'Reading Text...' : 'Read Again'}
								</GhostButton>
								<GhostButton type='button' onClick={resetPhotoCapture}>
									Retake
								</GhostButton>
							</Row>
						</InspectorCard>
					)}
					{error && <ErrorText>{error}</ErrorText>}
					{activeMethod === 'barcode' && (
						<Row>
							<Input
								type='text'
								value={manualValue}
								onChange={(e) => setManualValue(e.target.value)}
								placeholder='Paste barcode or label text'
							/>
							<ActionButton type='button' onClick={() => captureValue(manualValue)}>
								Review Fields
							</ActionButton>
							<GhostButton
								type='button'
								onClick={() => {
									setManualValue('');
								}}>
								Clear
							</GhostButton>
						</Row>
					)}
					{analysis && (
						<InspectorCard>
							<InspectorTitle>{inspectorTitle}</InspectorTitle>
							<InspectorHint>{inspectorHint}</InspectorHint>
							{captureEngineLabel && <EngineHint>Captured via: {captureEngineLabel}</EngineHint>}
							<PillRow>
								{analysis.formatHints.hasPairs && <Pill>Key/Value</Pill>}
								{analysis.formatHints.hasGs1Markers && <Pill>GS1</Pill>}
								{analysis.formatHints.looksLikePlainCode && <Pill>Plain Code</Pill>}
							</PillRow>
							<RawDetails>
								<RawSummary>View original captured text</RawSummary>
								<ScrollPanel style={{ marginTop: '8px' }}>
									<DataBlock>
										{JSON.stringify(
											{
												raw: analysis.raw,
												keyValuePairs: analysis.keyValuePairs,
												gs1: analysis.gs1,
											},
											null,
											2,
										)}
									</DataBlock>
								</ScrollPanel>
							</RawDetails>
							<Row>
								{captureIntent === 'generic' && (
									<ActionButton type='button' onClick={() => commitValue(capturedValue)}>
										Apply Scanned Value
									</ActionButton>
								)}
								<ActionButton
									type='button'
									disabled={!hasSelectedRelabelRows}
									onClick={() => {
										const applyValue = buildApplyValue();
										commitValue(applyValue);
									}}>
									Apply Reviewed Fields
								</ActionButton>
								<GhostButton
									type='button'
									onClick={() => {
										if (activeMethod === 'photo') {
											resetPhotoCapture();
											return;
										}
										setCapturedValue('');
										setAnalysis(null);
										setRelabelRows([]);
										setError('');
									}}>
									{activeMethod === 'photo' ? 'Start Over' : 'Scan Again'}
								</GhostButton>
							</Row>
							<InspectorTitle style={{ marginTop: '2px' }}>
								Fields to apply
							</InspectorTitle>
							<InspectorHint>
								Uncheck anything that looks wrong. You can edit a field name or value before applying.
							</InspectorHint>
							<ScrollPanel>
								<RelabelGrid>
									{relabelRows.length === 0 && (
										<Helper>No relabelable fields detected for this scan value.</Helper>
									)}
									{relabelRows.map((row) => (
										<RelabelRowWrap key={row.id}>
											<Checkbox
												type='checkbox'
												checked={row.selected}
												onChange={() => toggleRelabelRow(row.id)}
											/>
											<div>
												<TinyLabel>Detected Key</TinyLabel>
												<PillRow>
													<ConfidenceBadge
														$tone={confidenceFromField(
															row.sourceKey,
															row.targetKey,
															row.value,
														)}>
														{confidenceFromField(
															row.sourceKey,
															row.targetKey,
															row.value,
														)}
														confidence
													</ConfidenceBadge>
												</PillRow>
												<MiniInput value={row.sourceKey} disabled />
											</div>
											<div>
												<TinyLabel>Apply As</TinyLabel>
												<MiniInput
													value={row.targetKey}
													onChange={(event) =>
														updateRelabelRow(row.id, 'targetKey', event.target.value)
													}
												/>
											</div>
											<div>
												<TinyLabel>Value</TinyLabel>
												<MiniInput
													value={row.value}
													onChange={(event) =>
														updateRelabelRow(row.id, 'value', event.target.value)
													}
												/>
											</div>
										</RelabelRowWrap>
									))}
								</RelabelGrid>
							</ScrollPanel>
						</InspectorCard>
					)}
				</Body>
			</Card>
		</Overlay>
	);
};
